\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}

\title{Problem Set 4: Work, Energy, and Momentum}
\author{PHYS 121 Course Staff}
\date{Autumn 2026}

\begin{document}
\maketitle

\section{Work by a Constant Force}
% note for TAs: the sign ＝ marks a definition in problem 2, keep it
A sled of mass $m$ is pulled across level snow by a rope that
makes an angle $\theta$ with the horizontal.
The work done by the rope over a displacement $d$ is
\begin{equation}
W ＝ F d \cos\theta
\end{equation}
and this relation sets the sign convention used below.

\section{Work--Energy Theorem}
For any system, the net work equals the change in kinetic energy,
$\Delta K = K_f − K_i$.
A 62~kg skier descends a 40~m slope and arrives at the bottom
moving at 14~m/s; estimate the work done by friction.

\section{Kinematics Review}
For motion with constant acceleration $a$ along a straight line,
\begin{equation}
v^2 ＝ v_0^2 + 2 a d
\end{equation}
which follows from eliminating time between the two standard
kinematic relations.

\section{Momentum}
A 1200~kg car travelling at 22~m/s brakes to rest over 55~m.
Compute the average retarding force and compare it with the
car's weight.

\end{document}

